import { expect, expectStatus, test } from "../../fixtures";

const KINDS = ["w9", "insurance_certificate", "contract"] as const;

function uniqueSuffix(): string {
  return `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

test.describe("vendor lifecycle", () => {
  test(
    "rejecting one document sends the whole vendor back",
    { tag: "@LIF-02" },
    async ({ apiAs }) => {
      // Arrange: a member builds a vendor with three documents and submits it.
      const suffix = uniqueSuffix();
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");

      const created = await expectStatus<{ id: string }>(
        await member.post("/api/vendors", {
          data: {
            name: `Lifecycle Vendor ${suffix}`,
            category: "services",
            contact_email: `lifecycle-${suffix}@example.test`,
          },
        }),
        201,
      );
      const vendorId = created.id;

      const documentIdByKind = new Map<string, string>();
      for (const kind of KINDS) {
        const doc = await expectStatus<{ id: string }>(
          await member.post(`/api/vendors/${vendorId}/documents`, {
            multipart: {
              kind,
              file: {
                name: `${kind}-${suffix}.pdf`,
                mimeType: "application/pdf",
                buffer: Buffer.from(`%PDF-1.4 ${kind} ${suffix}`),
              },
            },
          }),
          201,
        );
        documentIdByKind.set(kind, doc.id);
      }

      // Wait for every document to finish extraction.
      for (const documentId of documentIdByKind.values()) {
        await expect
          .poll(async () => {
            const body = await expectStatus<{ status: string }>(
              await member.get(`/api/documents/${documentId}`),
              200,
            );
            return body.status;
          })
          .toBe("extracted");
      }

      await expectStatus(await member.post(`/api/vendors/${vendorId}/submit`), 200);

      // Locate the pending "contract" extraction.
      const contractDocId = documentIdByKind.get("contract");
      expect(contractDocId).toBeTruthy();
      const contractExtraction = await expectStatus<{ id: string; status: string }>(
        await member.get(`/api/documents/${contractDocId}/extraction`),
        200,
      );
      expect(contractExtraction.status).toBe("pending_review");

      // Act: reviewer rejects the contract extraction.
      const decided = await expectStatus<{ id: string; status: string; review_note: string | null }>(
        await reviewer.post(`/api/extractions/${contractExtraction.id}/decision`, {
          data: { decision: "reject", note: "Wrong counterparty" },
        }),
        200,
      );

      // Assert: the extraction is rejected with the note.
      expect(decided.status).toBe("rejected");
      expect(decided.review_note).toBe("Wrong counterparty");

      // Assert: the vendor is rejected as a whole.
      const vendor = await expectStatus<{ status: string }>(
        await reviewer.get(`/api/vendors/${vendorId}`),
        200,
      );
      expect(vendor.status).toBe("rejected");

      // Assert: audit events recorded in order, extraction first, then vendor.
      const audit = await expectStatus<{ items: { action: string }[] }>(
        await reviewer.get(`/api/vendors/${vendorId}/audit`),
        200,
      );
      const actions = audit.items.map((event) => event.action);
      const extractionIndex = actions.indexOf("extraction.rejected");
      const vendorIndex = actions.indexOf("vendor.rejected");
      expect(extractionIndex).toBeGreaterThanOrEqual(0);
      expect(vendorIndex).toBeGreaterThanOrEqual(0);
      expect(extractionIndex).toBeLessThan(vendorIndex);
    },
  );
});
